B.arL=s(["Mouais. C\u2019est juste.","Pas mal, hein.","Ok, tu g\xe8res.","Tranquille. Bonne r\xe9ponse.","Bon. Je suis presque impressionn\xe9e."],t.s)
B.au6=s(["Bof. \xc7a arrive.","Rat\xe9. On s\u2019en remet.","Pas grave, on refait.","Hmm. Presque. Enfin\u2026 non."],t.s)
B.aub=s(["{n} d\u2019affil\xe9e. Tu forces un peu, l\xe0.","{n} de suite\u2026 Ok, respect.","Encore ? {n}. Tu ne te fatigues jamais ?"],t.s)
B.atq=s(["Z\xe9ro faute. Je ne dis rien, mais c\u2019est fort.","Sans faute. Tu m\u2019as presque r\xe9veill\xe9e."],t.s)
B.aBo=s(["C\u2019est fait. Proprement.","Pas mal du tout. Je retourne m\u2019asseoir."],t.s)
B.aut=s(["Laborieux, mais termin\xe9. \xc7a compte.","On a vu mieux, on a vu pire. Reviens demain."],t.s)
B.axU=s(["\xc9coute. Une fois suffit, normalement.","Tends l\u2019oreille. Je ne r\xe9p\xe8te pas\u2026 si, je r\xe9p\xe8te."],t.s)
B.aGy=s(["\xc0 toi. Sans stress.","R\xe9p\xe8te apr\xe8s moi. Tranquille."],t.s)
B.aMy=new A.bw([B.bV,B.arL,B.bW,B.au6,B.c8,B.aub,B.c9,B.atq,B.ca,B.aBo,B.cb,B.aut,B.cc,B.axU,B.cd,B.aGy],t.Sb)
B.aug=s(["H\xe9\xe9\xe9 ! C\u2019est \xe7a m\xeame !","Voil\xe0 ! Tu as tout compris !","Bravo, la famille !","Ha ha ! Trop fort !","\xc7a, c\u2019est du bon travail !"],t.s)
B.arZ=s(["A\xefe ! Ce n\u2019est rien, on recommence !","\xc7a arrive \xe0 tout le monde, m\xeame \xe0 moi !","Pas grave, on rit et on reprend !","Presque ! La prochaine est pour toi !"],t.s)
B.akG=s(["{n} de suite ! On ne t\u2019arr\xeate plus !","{n} ! Le march\xe9 entier t\u2019applaudit !","Combo de {n} ! Je danse pour toi !"],t.s)
B.anX=s(["Sans faute ! Aujourd\u2019hui, c\u2019est toi le patron !","Z\xe9ro erreur ! \xc7a se f\xeate !"],t.s)
B.ak0=s(["Le\xe7on boucl\xe9e ! Tu avances bien, dis donc !","C\u2019est fait ! Je suis fier de toi !"],t.s)
B.aAG=s(["C\u2019\xe9tait dur, mais tu as tenu ! \xc7a, c\u2019est le courage !","Tu n\u2019as pas l\xe2ch\xe9 ! Demain ce sera plus facile !"],t.s)
B.awg=s(["\xc9coute bien, c\u2019est joli \xe0 entendre !","Ouvre grand les oreilles !"],t.s)
B.aDk=s(["\xc0 toi ! Dis-le bien fort !","R\xe9p\xe8te avec moi, sans g\xeane !"],t.s)
B.aMB=new A.bw([B.bV,B.aug,B.bW,B.arZ,B.c8,B.akG,B.c9,B.anX,B.ca,B.ak0,B.cb,B.aAG,B.cc,B.awg,B.cd,B.aDk],t.Sb)
B.aDD=s(["C\u2019est bien, continue comme \xe7a.","Tr\xe8s bien. Je savais que tu y arriverais.","Bonne r\xe9ponse, doucement mais s\xfbrement.","Tu progresses, je le vois.","Parfait. Prends ton temps."],t.s)
B.aow=s(["Ce n\u2019est pas grave. On reprend ensemble.","Doucement. L\u2019erreur fait partie du chemin.","Regarde bien la r\xe9ponse, tu la retiendras.","Courage, tu y es presque."],t.s)
B.ajj=s(["{n} bonnes r\xe9ponses de suite. Je suis fi\xe8re de toi.","{n} d\u2019affil\xe9e, sans te presser. Bravo.","{n} ! Tu vois que tu peux."],t.s)
B.aAN=s(["Bravo pour ce sans-faute, vraiment.","Pas une erreur. Quel beau travail."],t.s)
B.axy=s(["Le\xe7on termin\xe9e. Chaque jour un peu plus.","C\u2019est fait. Tu avances \xe0 ton rythme, et c\u2019est le bon."],t.s)
B.aCN=s(["Tu as tenu jusqu\u2019au bout, et c\u2019est \xe7a qui compte.","Ce n\u2019\xe9tait pas facile. Repose-toi, on reprend demain."],t.s)
B.aoy=s(["\xc9coute tranquillement.","\xc9coute, autant de fois que tu veux."],t.s)
B.azo=s(["R\xe9p\xe8te apr\xe8s moi, doucement.","\xc0 ton tour, sans te presser."],t.s)
B.aMo=new A.bw([B.bV,B.aDD,B.bW,B.aow,B.c8,B.ajj,B.c9,B.aAN,B.ca,B.axy,B.cb,B.aCN,B.cc,B.aoy,B.cd,B.azo],t.Sb)
B.amp=s(["Eh, tu triches ou quoi ? C\u2019est juste !","Pas mal pour quelqu\u2019un qui dormait hier.","Bien vu ! Je te croyais moins rapide.","Correct ! Tu m\u2019\xe9tonnes, l\xe0.","Bonne r\xe9ponse. Ne prends pas la grosse t\xeate."],t.s)
B.ajd=s(["Oups ! Je garde \xe7a pour moi, promis.","Rat\xe9 ! Mais j\u2019ai vu pire\u2026 moi, par exemple.","Ha ! Presque. Presque, hein.","Ce n\u2019est pas \xe7a. Je ne dirai rien \xe0 personne."],t.s)
B.amH=s(["{n} de suite ? Tu veux ma place ou quoi ?","{n} ! D\u2019accord, j\u2019arr\xeate de te taquiner.","Combo de {n}. Bon, l\xe0, chapeau."],t.s)
B.aj3=s(["Sans faute ? Tu avais les r\xe9ponses dans la poche, avoue.","Z\xe9ro erreur. Je n\u2019ai m\xeame pas de blague."],t.s)
B.av8=s(["Termin\xe9 ! Tu vois, quand tu veux.","Le\xe7on finie. Je te taquine, mais c\u2019est bien."],t.s)
B.aAR=s(["Tu as transpir\xe9, mais c\u2019est pli\xe9 !","Dur, dur\u2026 mais tu n\u2019as pas fui. Respect."],t.s)
B.anN=s(["\xc9coute bien, je ne le dirai pas deux fois. Si, bon, d\u2019accord.","Ouvre tes oreilles, petit malin."],t.s)
B.aF_=s(["\xc0 toi ! Et articule, hein.","R\xe9p\xe8te apr\xe8s moi, sans rire."],t.s)
B.aMj=new A.bw([B.bV,B.amp,B.bW,B.ajd,B.c8,B.amH,B.c9,B.aj3,B.ca,B.av8,B.cb,B.aAR,B.cc,B.anN,B.cd,B.aF_],t.Sb)
B.aq_=s(["C\u2019est bien, mon enfant.","Voil\xe0. Tu parles comme chez nous.","Bonne r\xe9ponse. La patience paie.","C\u2019est juste. Cette langue te va bien.","Tr\xe8s bien. Tu \xe9coutes, donc tu apprends."],t.s)
B.aBy=s(["Ce n\u2019est rien. On tombe, on se rel\xe8ve.","Doucement, mon enfant. Recommence.","M\xeame le vieux lion a appris \xe0 marcher.","L\u2019erreur d\u2019aujourd\u2019hui est le savoir de demain."],t.s)
B.asg=s(["{n} de suite. Tu as de la t\xeate, mon enfant.","{n} bonnes r\xe9ponses. Le village sera fier.","{n} ! Continue, je t\u2019\xe9coute."],t.s)
B.anZ=s(["Pas une faute. Je n\u2019ai rien \xe0 ajouter, c\u2019est parfait.","Sans faute. Va, tu as bien m\xe9rit\xe9 ton repas."],t.s)
B.aFM=s(["La le\xe7on est finie. Petit \xe0 petit, la langue entre.","C\u2019est bien. Reviens demain, je serai l\xe0."],t.s)
B.azF=s(["C\u2019\xe9tait long, mais tu n\u2019es pas parti. C\u2019est \xe7a, apprendre.","Tu as pein\xe9, tu as fini. Voil\xe0 la vraie force."],t.s)
B.al0=s(["\xc9coute comme on \xe9coute un conte.","Tends l\u2019oreille, mon enfant."],t.s)
B.aBd=s(["R\xe9p\xe8te apr\xe8s moi, mon enfant.","\xc0 toi. Parle sans peur."],t.s)
B.aMw=new A.bw([B.bV,B.aq_,B.bW,B.aBy,B.c8,B.asg,B.c9,B.anZ,B.ca,B.aFM,B.cb,B.azF,B.cc,B.al0,B.cd,B.aBd],t.Sb)
B.azb=s(["Ouiii ! C\u2019est la bonne !","Trop bien ! Tu m\u2019apprends, apr\xe8s ?","Gagn\xe9 !","Waouh, tu sais d\xe9j\xe0 \xe7a ?","Bonne r\xe9ponse ! Encore une !"],t.s)
B.alK=s(["Oh\u2026 ce n\u2019\xe9tait pas \xe7a. Moi aussi je me trompe.","Rat\xe9 ! On r\xe9essaie ?","Zut ! La prochaine, on l\u2019aura.","Ce n\u2019est pas grave, la ma\xeetresse dit qu\u2019on apprend comme \xe7a."],t.s)
B.aD0=s(["{n} de suite ! C\u2019est trop fort !","{n} ! Je veux faire pareil !","Combo de {n} ! On continue ?"],t.s)
B.aAm=s(["Sans faute ! Tu auras une bonne note !","Z\xe9ro faute ! C\u2019est comme \xe0 l\u2019\xe9cole, mais en mieux !"],t.s)
B.ap2=s(["Fini ! On en fait une autre ?","Le\xe7on termin\xe9e ! J\u2019ai appris plein de choses avec toi."],t.s)
B.ast=s(["C\u2019\xe9tait difficile, mais on a fini !","Ouf ! On a r\xe9ussi quand m\xeame !"],t.s)
B.aA5=s(["\xc9coute, \xe9coute ! C\u2019est quoi, ce mot ?","Chut\u2026 on \xe9coute."],t.s)
B.azR=s(["\xc0 toi de parler !","R\xe9p\xe8te ! Moi aussi je m\u2019entra\xeene."],t.s)
B.aMv=new A.bw([B.bV,B.azb,B.bW,B.alK,B.c8,B.aD0,B.c9,B.aAm,B.ca,B.ap2,B.cb,B.ast,B.cc,B.aA5,B.cd,B.azR],t.Sb)
B.avB=s(["Magnifique ! \xc7a sonne juste !","Oh l\xe0 l\xe0, quelle oreille !","Bravo ! On dirait une chanson.","C\u2019est \xe7a ! En plein dans le ton.","Parfait, parfait, parfait !"],t.s)
B.aoY=s(["Fausse note ! Ce n\u2019est rien, on reprend.","Oups ! M\xeame les stars r\xe9p\xe8tent.","Pas tout \xe0 fait. On la refait, en rythme.","Rat\xe9, mais avec style !"],t.s)
B.aiQ=s(["{n} de suite ! Quel tempo !","{n} ! Le public est debout !","Combo de {n} ! Tu es en tourn\xe9e ou quoi ?"],t.s)
B.axV=s(["Sans fausse note ! Ovation debout !","Z\xe9ro faute ! Rappel, rappel !"],t.s)
B.ain=s(["Le\xe7on termin\xe9e ! Belle prestation.","C\u2019est dans la bo\xeete ! Bravo l\u2019artiste."],t.s)
B.akT=s(["Quelques fausses notes, mais tu as fini le concert !","Pas facile, ce morceau. Tu l\u2019as tenu jusqu\u2019au bout."],t.s)
B.ans=s(["\xc9coute la m\xe9lodie du mot.","\xc9coute bien : chaque mot a sa musique."],t.s)
B.aBA=s(["\xc0 toi le micro !","Chante-le\u2026 enfin, dis-le !"],t.s)
